pipeline {
  agent { label 'docker' }
  options { timeout(time: 45, unit: 'MINUTES'); timestamps(); disableConcurrentBuilds(); buildDiscarder(logRotator(numToKeepStr: '20')) }
  environment {
    IMAGE = "registry.example.com/team/app"   // placeholder
    TAG   = "${env.GIT_COMMIT.take(8)}"
    REG   = credentials('registry-creds')
  }
  stages {
    stage('Build')   { steps { sh './mvnw -B -DskipTests package' } }
    stage('Test')    { steps { sh './mvnw -B test' } post { always { junit 'target/surefire-reports/*.xml' } } }
    stage('Sonar')   { steps { withSonarQubeEnv('sonar') { sh './mvnw -B sonar:sonar' } } }
    stage('Gate')    { steps { timeout(time: 10, unit: 'MINUTES') { waitForQualityGate abortPipeline: true } } }
    stage('Image')   { steps { sh 'docker build -t $IMAGE:$TAG .' } }
    stage('Trivy')   { steps { sh 'trivy image --exit-code 1 --severity HIGH,CRITICAL $IMAGE:$TAG' } }
    stage('Push')    { steps { sh 'echo $REG_PSW | docker login registry.example.com -u $REG_USR --password-stdin && docker push $IMAGE:$TAG' } }
    stage('GitOps')  { when { branch 'main' } steps { sh './ci/bump-tag.sh $IMAGE $TAG' } }
    stage('Argo CD') { when { branch 'main' } steps { sh 'argocd app sync app --grpc-web && argocd app wait app --health --timeout 300' } }
    stage('Smoke')   { when { branch 'main' } steps { sh 'curl -fsS https://app.example.com/health' } }
  }
  post { cleanup { cleanWs() } }
}

pipeline {
  agent { label 'deck' }
  environment { KONG_ADDR = 'http://kong-admin.internal:8001' }   // placeholder
  stages {
    stage('Validate') { steps { sh 'deck gateway validate kong.yaml' } }
    stage('Backup')   { steps { sh 'deck gateway dump -o backup-${BUILD_NUMBER}.yaml --kong-addr $KONG_ADDR'; archiveArtifacts 'backup-*.yaml' } }
    stage('Diff')     { steps { sh '''
      deck gateway diff -s kong.yaml --kong-addr $KONG_ADDR --no-color | tee diff.txt
      if grep -E '^deleting ' diff.txt; then echo 'Deletions found: blocked'; exit 1; fi
    ''' } }
    stage('Approve')  { when { branch 'main' } steps { input message: 'Apply this diff?' } }
    stage('Sync')     { when { branch 'main' } steps { sh 'deck gateway sync -s kong.yaml --kong-addr $KONG_ADDR' } }
    stage('Smoke')    { when { branch 'main' } steps { sh 'curl -fsS https://api.example.com/health' } }
  }
  post { failure { sh 'echo "restore: deck gateway sync -s backup-${BUILD_NUMBER}.yaml"' } }
}
